export const DATA_96: ReadingTest[] = [
  { id: "rd-175", num: 175, title: "Đề 175", timeMin: 60, parts: [
    { title: "The Rural Life Videos of Li Ziqi", paragraphs: ["In recent years, a young woman from Sichuan, China, named Li Ziqi has become known around the world for her quiet videos about country life. In each video, she cooks traditional meals, grows vegetables in her garden, and makes handmade crafts using simple tools. She films everything herself, often working alone from early morning until late at night. Even though she rarely speaks in her videos, millions of people watch them every month, drawn by the calm pace and beautiful natural scenery.", "Li Ziqi's videos look very different from most content found online today. She does not talk directly to the camera, and she almost never explains what she is doing step by step. Instead, viewers simply watch as she plants rice in a flooded field, weaves a basket from dried grass, or bakes bread in a small clay oven built by hand. The soundtrack of her videos is not music but the everyday sounds of the countryside: birds calling, water flowing, or a knife slowly cutting vegetables on a wooden board. This slow, quiet style helps busy viewers relax and feel, for a few minutes, far away from noisy city life.", "Because of this unusual style, Li Ziqi has built an enormous following on video platforms both inside and outside China. Her main channel has tens of millions of subscribers, and admirers from dozens of countries watch her uploads, including many who cannot understand a single word of Mandarin. In 2021, she was recognized for holding the record for the most subscribers on a Chinese-language YouTube channel, a record that surprised many industry observers at the time. Fans frequently describe watching one of her videos as taking a short holiday from the pressure of modern life, even if that holiday lasts only ten minutes.", "Li Ziqi's popularity has done more than entertain; it has also introduced traditional Chinese culture to a global audience. Through her videos, viewers see old-fashioned cooking methods, handmade tools, and seasonal festivals that many young people living in Chinese cities rarely experience anymore. A number of schools and cultural organizations have used clips from her channel to teach children about rural customs and traditional skills. Still, a few critics argue that her carefully edited scenes present an overly idealized picture of farm life, one that quietly leaves out the physical hardship and financial struggle that real farmers often face.", "In the middle of 2021, Li Ziqi unexpectedly stopped uploading new videos for more than a year, and her channel fell silent. Worried fans asked what had happened, but her production team gave only a brief statement, mentioning a business disagreement without going into detail. She eventually returned in 2023 with a new set of videos, and longtime fans welcomed her back with excitement. Today she continues to share peaceful scenes of rural life with the world, gently reminding busy viewers everywhere that a simpler, slower way of living can still be genuinely beautiful."], questions: [{ q: "According to the passage, Li Ziqi is originally from _______.", options: ["Yunnan Province", "Guangdong Province", "Sichuan Province", "Beijing City"], answer: 2 }, { q: "What is the main idea of the passage?", options: ["Li Ziqi gained fame for teaching step-by-step traditional recipes.", "Li Ziqi earned global fame through peaceful rural videos despite criticism.", "Li Ziqi became famous mainly after taking an unexpected public break.", "Li Ziqi built a massive following as China's top-rated chef."], answer: 1 }, { q: "The word \"idealized\" in paragraph 4 is closest in meaning to _______.", options: ["criticized", "simplified", "romanticized", "documented"], answer: 2 }, { q: "In 2021, Li Ziqi was recognized for _______.", options: ["Setting a subscriber record for a Chinese-language channel.", "Publishing her first international cookbook for global readers.", "Winning a major documentary film award for rural culture.", "Opening a rural cultural museum in her Chinese hometown."], answer: 0 }, { q: "According to the passage, which of the following is NOT mentioned as an activity Li Ziqi does in her videos?", options: ["growing vegetables in her garden", "baking bread in a clay oven", "painting traditional watercolor pictures", "weaving baskets from dried grass"], answer: 2 }, { q: "The word \"one\" in paragraph 4 refers to _______.", options: ["the idealized picture", "financial struggle", "rural customs", "traditional Chinese culture"], answer: 0 }, { q: "Why did Li Ziqi stop posting videos in 2021?", options: ["Her production team cited an undisclosed business disagreement.", "She spent a year recovering privately from a serious illness.", "She left China to study culinary arts at a university.", "She chose to focus full-time on farming with her family."], answer: 0 }, { q: "The word \"hardship\" in paragraph 4 is closest in meaning to _______.", options: ["difficulty", "inconvenience", "reputation", "tradition"], answer: 0 }, { q: "It can be inferred from the passage that the author most likely believes _______.", options: ["Li Ziqi's fans mainly watch her videos because they hope to learn practical farming skills at home", "Li Ziqi's videos are considered by most experts the only accurate record of rural Chinese life", "Li Ziqi will most likely stop making new videos again soon due to ongoing business problems", "Li Ziqi's videos, while beautifully made, do not tell the full story of rural farming life"], answer: 3 }, { q: "What is the author's overall attitude toward Li Ziqi in the passage?", options: ["Personal, based on individual travel experiences across rural regions.", "Balanced, presenting both her widespread appeal and valid criticisms.", "Critical, highlighting mostly negative consequences of idealized content.", "Promotional, encouraging online audiences to subscribe to her channel."], answer: 1 }] },
    { title: "The Platform Shift Among Generation Z", paragraphs: ["Although Facebook still ranks among the most widely used social media platforms in the world by total number of accounts, evidence gathered over the past several years suggests that its grip on the youngest generation of users has been steadily eroding . Surveys conducted among teenagers and young adults consistently show declining daily engagement with the platform, even as older users continue signing on in large numbers. This gradual shift has prompted researchers, marketers, and parents alike to ask the same question: where exactly are young people going instead, and why?", "The most commonly cited destinations are Snapchat and Instagram, two platforms that, while different in design, share features that appeal strongly to younger audiences. Snapchat's disappearing messages and playful filters offer a sense of spontaneity that many teenagers find preferable to the more permanent, curated posts typical of Facebook. Instagram, meanwhile, has managed to retain relevance by continuously adapting its format — most notably by introducing short-form video features that closely resemble those popularized by competing apps. Neither platform requires the kind of long-term, public profile-building that Facebook was originally designed around, a distinction that appears to matter a great deal to younger users.", "Some researchers argue that the underlying cause is not simply a preference for newer technology but a deeper shift in how young people wish to present themselves online. Whereas earlier generations often used Facebook to construct a lasting, semi-permanent record of their lives — photos, relationship updates, life milestones — many Gen Z users appear to favor more fleeting, less curated forms of self-expression. This is not to say that image matters less to them; if anything, the pressure to appear authentic, rather than polished, has simply taken a different form, one better suited to platforms built around temporary content.", "There is also a generational association at play that should not be underestimated. Because Facebook was adopted early on by parents, teachers, and even grandparents, many teenagers came to view it less as a space for peer interaction and more as a platform monitored by adults. Several studies have noted that teenagers, when asked directly, describe Facebook as being for \"older people,\" a perception that, once established, tends to become self-reinforcing regardless of any features the platform later introduces to attract younger users.", "None of this means Facebook has become irrelevant to Gen Z entirely. Many young users maintain a Facebook account for practical reasons — joining local community groups, buying and selling secondhand items on Facebook Marketplace, or staying connected with extended family members who are not active on other platforms. In these cases , however, the platform functions more like a utility than a primary space for social interaction, opened occasionally rather than checked throughout the day. This distinction, between a platform used out of necessity and one used out of genuine enjoyment, may explain why usage statistics alone can be misleading.", "The long-term consequences of this shift remain uncertain. Some analysts predict that Facebook's parent company will continue investing heavily in Instagram, effectively allowing one platform to age alongside its original user base while directing newer features toward the other. Others suggest that an entirely new platform, not yet dominant, could eventually capture Gen Z's attention in the same way Snapchat and Instagram once did, following a pattern of generational rotation that has repeated itself several times since the rise of social media roughly two decades ago.", "What seems clear, at least for now, is that generational loyalty to any single platform cannot be assumed. Just as Facebook once displaced earlier networks by offering something new, it may eventually be displaced itself — not necessarily because it has failed, but because the platforms young people gravitate toward tend to say something about who they want to be, not merely where their friends happen to be."], questions: [{ q: "According to the passage, which two platforms are most commonly cited as destinations for young users leaving Facebook?", options: ["TikTok and YouTube", "Snapchat and Instagram", "WhatsApp and Telegram", "Twitter and Pinterest"], answer: 1 }, { q: "The word \"eroding\" in paragraph 1 is closest in meaning to _______.", options: ["fading", "improving", "expanding", "weakening"], answer: 3 }, { q: "What is the main idea of the passage?", options: ["Instagram and Snapchat will soon replace Facebook entirely globally.", "Facebook remains widely used, but young users prefer other platforms.", "Young people abandoned Facebook mainly because parents joined the app.", "Facebook lost most global users due to inferior technological features."], answer: 1 }, { q: "According to the passage, which of the following is NOT given as a reason young people prefer Snapchat and Instagram over Facebook?", options: ["Snapchat's messages disappear rather than remaining permanently", "Both platforms offer significantly lower data and storage costs", "Instagram has added short-form video features", "Facebook is associated with parents and older relatives"], answer: 1 }, { q: "According to the passage, how do many teenagers describe Facebook, according to several studies?", options: ["as being 'for older people,' due to its early adoption by adults", "as less secure and more likely to expose personal information", "as too complicated and difficult for younger users to understand", "as a platform mainly for professional networking and job searching"], answer: 0 }, { q: "The phrase \"these cases\" in paragraph 5 refers to _______.", options: ["declining engagement among older Facebook users", "secondhand items sold on Facebook Marketplace", "extended family members who are not active on other platforms", "situations where teenagers use Facebook mainly for practical purposes"], answer: 3 }, { q: "According to the passage, which of the following is mentioned as a practical reason some Gen Z users keep a Facebook account?", options: ["streaming live sports events broadcast only on Facebook", "buying and selling secondhand items through Facebook Marketplace", "playing multiplayer games developed specifically for the platform", "applying for jobs listed exclusively on Facebook's job board"], answer: 1 }, { q: "The word \"curated\" in paragraph 3 is closest in meaning to _______.", options: ["widely criticized", "carefully selected", "removed entirely", "shared randomly"], answer: 1 }, { q: "Based on information in the passage, it can be inferred that a decline in teenagers' daily engagement with Facebook does NOT necessarily mean that _______.", options: ["those same teenagers have stopped using Facebook accounts completely", "older Facebook users are also reducing their daily time on the app", "Instagram will eventually overtake Facebook in total number of accounts", "Snapchat's disappearing messages are the single biggest reason for this"], answer: 0 }, { q: "What is the author's primary purpose in writing this passage?", options: ["To criticize Gen Z for abandoning long-term online self-presentation.", "To persuade readers that Facebook will disappear in a few years.", "To explore various possible explanations for Gen Z's platform shift.", "To promote Instagram and Snapchat as superior choices for all ages."], answer: 2 }] },
    { title: "The Last City", paragraphs: ["Long before I set foot on the gravel track that climbs toward what locals simply call \"the last city,\" I had assumed that the appeal of such a place would lie in its remoteness alone. What I had not anticipated was how quickly that remoteness would begin to feel less like an absence and more like a kind of company. The settlement, a cluster of perhaps forty buildings clinging to a ridge above the tree line, earns its nickname not because it is technically the final inhabited point on any map, but because, for those who arrive on foot, it is the last place that still resembles a city at all.", "Reaching it required four days of walking, though the difficulty of the route had less to do with altitude than with the way each day seemed to erase the previous one's sense of progress. Rivers that appeared, according to the map, to be minor crossings routinely demanded hour-long detours; a ridge that looked, from a distance, like the day's final obstacle would reveal, on arrival, three further ridges behind it. It was only on the third evening, exhausted and disoriented by a landscape that refused to be measured in the usual way, that I began to understand why the townspeople speak of the walk itself, rather than the destination, as the defining experience.", "Anthropologists who have studied the settlement suggest that its isolation, rather than eroding a sense of community, may have intensified it, though they are careful to note that this effect is not unique to remote towns and could equally reflect selection: those unsuited to such isolation simply do not stay long enough to be counted. Whatever the cause, the town's roughly two hundred residents maintain a density of mutual obligation that would be unusual even in a small city. Nearly every adult, I was told, holds some formal responsibility — tending the water system, managing the single school, coordinating supply runs — that cannot easily be delegated or ignored.", "[1] None of this, however, should be mistaken for a life free of hardship. [2] Supplies that cannot be grown or made locally arrive only twice a month, carried in by mule train along the same route I had walked, and prices reflect that scarcity: a single bag of flour costs roughly four times what it would in the nearest large town. [3] Several residents mentioned, almost in passing, that they had considered leaving after a particularly harsh winter, only to find that the prospect of returning to a conventional job elsewhere felt, in their words, more foreign than the isolation itself. [4]", "What struck me most, though, was not the hardship but the particular quality of attention that isolation seemed to demand. Without the usual background noise of traffic, notifications, or distant construction, small events — a change in wind direction, a delay in the mule train, a disagreement over water rights — acquired a weight that would seem disproportionate anywhere else. Whether this heightened attentiveness constitutes a genuine improvement in quality of life, or simply a narrowing of one's field of concern until it fits the available space, is a question the residents themselves seem divided on, and one I found myself unable to answer with any confidence.", "Tourism, predictably, has begun to complicate this arrangement, even though its scale remains modest for now. A handful of trekkers, myself included, now make the journey each season, drawn by accounts of the settlement's self-sufficiency, and their presence has introduced a small but steady source of income that several residents describe as welcome, if occasionally intrusive. Whether this trickle of outside interest will, over the coming decade, reshape the town's economy in ways that echo other once-remote destinations, or whether the difficulty of the approach will continue to limit numbers naturally, remains, by the residents' own admission, an open question.", "I left after five days, descending the same route by which I had come, and found the return journey considerably faster, not because the terrain had changed but because I no longer expected the walk to resolve into anything other than what it was. The last city, I suspect, earns its name less from geography than from the particular relationship its residents have negotiated with distance itself — a relationship that outsiders like myself can observe, and even briefly inhabit, but never fully claim to understand after a visit measured in days rather than years."], questions: [{ q: "According to the passage, why do supplies delivered to the settlement cost significantly more than in nearby towns?", options: ["The nearest large town restricts how many goods may be exported.", "Residents refuse to grow or produce any food locally themselves.", "The town imposes an additional local tax on all imported goods.", "Infrequent, mule-based delivery routes limit supply and raise costs."], answer: 3 }, { q: "The word \"erase\" in paragraph 2 is closest in meaning to _______.", options: ["measure", "confirm", "postpone", "eliminate"], answer: 3 }, { q: "What is the main idea of the passage?", options: ["The passage documents physical difficulty, concluding the journey is worthless.", "Isolation creates deep social bonds alongside hardship with uncertain trade-offs.", "Tourism has already transformed the economy and destroyed local self-sufficiency.", "Isolation alone fosters strong social ties without requiring communal effort."], answer: 1 }, { q: "Based on paragraph 3, it can be inferred that the anthropologists' explanation for the town's strong sense of community _______.", options: ["applies equally well to explain why tourism has recently increased in the area", "is presented as certain, though the passage never actually questions its accuracy", "may be confounded by the fact that only certain people remain long enough to be studied", "has been strongly confirmed by long-term studies of many other remote settlements"], answer: 2 }, { q: "According to the passage, which of the following is NOT mentioned as a formal responsibility held by residents of the settlement?", options: ["coordinating every single supply run", "overseeing seasonal tourist trekking routes", "tending the town's water system", "managing the settlement's only school"], answer: 1 }, { q: "The phrase \"this trickle\" in paragraph 6 refers to _______.", options: ["the town's traditional self-sufficiency practices", "the steady income generated by visiting trekkers", "outside accounts describing the settlement", "the difficulty of the approach itself"], answer: 1 }, { q: "According to the passage, how did the writer's experience of the return journey differ from the journey to the settlement, and why?", options: ["The return felt slower because of extra supplies being carried.", "The return felt faster because the writer took a direct route.", "The return felt faster because expectations about the walk changed.", "The return felt unchanged in both travel speed and mindset."], answer: 2 }, { q: "What is the writer's overall attitude toward the settlement and its way of life, as expressed in the passage?", options: ["Scientific, focusing on cataloguing anthropological data without personal reflection.", "Dismissive, viewing the residents' extreme isolation as impractical and pointless.", "Purely celebratory, presenting the remote settlement as an ideal lifestyle.", "Reflective, appreciating community resilience while remaining uncertain about trade-offs."], answer: 3 }, { q: "The word \"disproportionate\" in paragraph 5 is closest in meaning to _______.", options: ["excessive", "predictable", "irrelevant", "temporary"], answer: 0 }, { q: "Which of the following square brackets [1] , [2] , [3] , or [4] best indicates where the following sentence could be added? 'Yet none of them, in the end, chose to go.'", options: ["[1]", "[2]", "[3]", "[4]"], answer: 3 }] },
    { title: "Rethinking the Boomerang Generation", paragraphs: ["The image of the \"boomerang\" adult — a young person who leaves home, only to return within a few years — has become so familiar in public discourse that it risks obscuring rather than clarifying what is actually happening to early-career trajectories. It would be a mistake, however, to treat the trend as evidence of a single, uniform cause, whether that cause is framed as economic necessity, cultural preference, or generational fragility; the reality, as several recent studies suggest, appears considerably more layered than any of these framings alone can capture.", "Housing costs are, unsurprisingly, central to most explanations, though the precise mechanism deserves closer scrutiny than it typically receives. In many metropolitan areas, the ratio of median home price to median entry-level income has grown so sharply over the past two decades that homeownership, for a graduate entering the workforce today, functions less as a distant but attainable milestone than as what some commentators have started calling a pipe dream — an aspiration retained more out of habit than realistic planning. This does not mean the aspiration has disappeared; if anything, surveys suggest it remains widely held, even as fewer respondents expect to achieve it within the timeframe their parents once considered normal.", "Whether this gap between aspiration and expectation constitutes a genuine psychological burden, or whether younger adults have simply recalibrated their sense of a \"normal\" timeline without much distress, remains disputed among researchers. What does seem clearer is that returning to a parental household, once treated primarily as a marker of failure to launch, is increasingly understood — by the young adults themselves, if not always by their parents — as a rational financial strategy, one that allows savings to accumulate at a rate that independent living would not permit.", "A parallel, and arguably related, shift has taken place in attitudes toward employment itself, particularly since the disruptions of the pandemic years. Where previous generations were often encouraged to view a single, stable job as both an economic necessity and a marker of adult identity, a growing proportion of younger workers now appear to treat frequent job changes, and in some cases the deliberate combination of several part-time or freelance roles, not as a fallback position but as a preferred arrangement. Employers, somewhat predictably, have tended to describe this shift using less flattering language, characterizing it variously as disloyalty, restlessness, or an unwillingness to commit.", "Such characterizations, however, may say as much about employer expectations formed in a different economic era as they do about the workers themselves. Several labor economists have argued — though not without dissent from colleagues who caution against overstating the shift — that what looks like restlessness might more accurately be described as a rational response to an employment landscape in which long-term loyalty is rewarded far less reliably than it once was, given the frequency with which companies themselves now restructure , relocate, or eliminate positions with limited notice.", "It would be too simple, though, to characterize this shift as purely a matter of economic calculation on the workers' side. Interviews conducted with young adults who have deliberately chosen part-time or multiple-role arrangements over a single full-time position suggest that considerations of flexibility, mental health, and control over one's schedule factor at least as heavily as income optimization, even when the arrangements in question do not clearly pay more, and sometimes pay measurably less, than the conventional alternative they replaced.", "Taken together, these patterns suggest that what is often described, somewhat dismissively, as a generation reluctant to grow up may instead reflect a generation adapting, not always by choice, to housing and labor markets that no longer function the way they did for the generation that designed the expectations still being applied to them. Whether this adaptation proves temporary, easing as economic conditions shift, or whether it marks a more lasting reorganization of how adulthood itself is sequenced, is a question current data cannot yet answer with confidence.", "These two threads — housing affordability and employment structure — are not unrelated, since the same generation navigating a stretched mortgage market is also absorbing a labor market that increasingly rewards adaptability over tenure. Understood this way, the boomerang phenomenon looks less like an isolated housing story and more like one symptom of a broader realignment between economic structures and the life stages they were once assumed to support."], questions: [{ q: "According to the passage, what does the growing gap between median home prices and entry-level income mean for how homeownership functions for many recent graduates?", options: ["It has become entirely unattainable, with almost no graduates expecting to ever own a home", "It has shifted from a realistic milestone to a persistently held but less achievable ideal", "It has caused graduates to prioritize renting permanently over any future homeownership plans", "It has led most graduates to abandon the goal of homeownership altogether within a decade"], answer: 1 }, { q: "The word \"recalibrated\" in paragraph 3 is closest in meaning to _______.", options: ["publicized", "adjusted", "abandoned", "exaggerated"], answer: 1 }, { q: "Regarding the relationship between employment attitudes and economic conditions, the passage suggests that _______.", options: ["Job-hopping is driven mainly by declining employer loyalty.", "Job-hopping stems from economic instability despite researchers' objections.", "Job-hopping reflects rational responses to employers alongside personal factors.", "Job-hopping is strictly a rational response to unstable employers."], answer: 2 }, { q: "What is the main idea of the passage?", options: ["Young adults are fundamentally less motivated toward financial independence.", "The boomerang trend stems from interconnected economic and personal factors.", "Housing costs are the sole driver of shifting adult trajectories.", "Employer criticism of job-hopping is completely unjustified and biased."], answer: 1 }, { q: "According to the passage, which of the following is NOT mentioned as a reason young adults choose part-time or multiple-role work arrangements over a single full-time job?", options: ["considerations related to mental health", "greater flexibility over one's schedule", "guaranteed higher overall income than full-time work", "a desire for more control over daily routines"], answer: 2 }, { q: "According to the passage, why might returning to live with parents no longer be viewed primarily as a sign of failure?", options: ["because it is increasingly seen as a rational strategy allowing faster savings accumulation", "because government housing policy now requires young adults to live with relatives first", "because parents increasingly encourage their adult children to remain at home indefinitely", "because most employers now expect new graduates to live with family during their careers"], answer: 0 }, { q: "The phrase \"this adaptation\" in paragraph 7 refers to _______.", options: ["Employers choosing to restructure companies without advance notice.", "Young adults adjusting behaviors to changed housing and job markets.", "Parents encouraging their adult children to stay home longer.", "The description framing young adults as reluctant to grow up."], answer: 1 }, { q: "What is the author's overall stance toward the common characterization of boomerang-generation young adults as \"reluctant to grow up\"?", options: ["Skeptical, suggesting it overlooks structural economic and labor pressures.", "Indifferent, treating the debate as largely unimportant to the argument.", "Supportive, agreeing that personal reluctance explains the current trend.", "Neutral, presenting the characterization without offering any critical evaluation."], answer: 0 }, { q: "The word \"restructure\" in paragraph 5 is closest in meaning to _______.", options: ["recruit", "relocate", "reward", "reorganize"], answer: 3 }, { q: "According to the passage, how does the author ultimately frame the relationship between housing affordability and employment trends among young adults?", options: ["as two entirely separate phenomena that happen to affect the same generation coincidentally", "as connected symptoms of a broader shift in how economic structures support different life stages", "as proof that government policy failures are the single root cause of both trends", "as evidence that young adults are financially irresponsible in both housing and career decisions"], answer: 1 }] },
  ] },
  { id: "rd-195", num: 195, title: "Đề 195", timeMin: 60, parts: [
    { title: "Life on a Modern Pig Farm", paragraphs: ["Pig farming has been part of rural economies for thousands of years, and today it remains one of the most widespread forms of livestock production across the world. In many countries, small family-run farms still raise a handful of pigs for local markets, while large commercial operations manage thousands of animals under a single roof. Vietnam, in particular, has a long tradition of pig raising, with the animal appearing frequently in folk stories and traditional festivals. Modern farms, however, look very different from the backyard pens of the past, relying instead on carefully planned systems that combine science with everyday practical knowledge.", "Feeding is one of the most important daily tasks on any pig farm, because the amount and type of food a pig eats directly affects both its health and the quality of the meat it eventually produces. Young piglets typically drink their mother's milk for several weeks before gradually being introduced to a mixture of grains, soybean meal, and vitamins. As the pigs grow larger, farmers adjust the feed to include more energy-rich ingredients such as corn, which helps the animals gain weight steadily rather than too quickly. Clean water must always be available, since pigs can become dehydrated and stressed surprisingly fast in hot weather. Housing also matters a great deal; pens that are too crowded tend to increase fighting among the animals and make it easier for illnesses to spread. Farmers often keep piglets separate from older pigs during the first few weeks, since housing them together can lead to injuries from more aggressive animals.", "Because pigs are raised so closely together, disease control is treated as a serious and ongoing responsibility rather than an occasional task. Veterinarians recommend a regular schedule of vaccinations to protect against common illnesses, and many farms now keep detailed health records for every animal. When an outbreak such as African swine fever does occur, it can spread with alarming speed and force farmers to cull entire herds within days, wiping out years of careful breeding work. For this reason, most modern farms restrict outside visitors, disinfect vehicles before they enter the property, and separate newly arrived animals from the rest of the herd for a period of observation.", "Pork remains one of the most consumed meats globally, and the industry that supplies it generates substantial income for farmers, feed suppliers, and exporters alike. Prices, though, can swing sharply within a single year, since they depend on factors ranging from grain costs to sudden shifts in consumer demand. A farmer who expands too quickly during a period of high prices may find, only months later, that falling prices have made the investment far riskier than it first appeared. Some governments respond to these swings by offering subsidies or temporary price supports, hoping to keep smaller farms from being pushed out of the market entirely.", "Large-scale pig farming, while economically important, also raises environmental concerns that communities near major farms are increasingly vocal about. Waste from thousands of animals must be collected, treated, and often converted into fertilizer, a process that, if managed poorly, can pollute nearby rivers and contaminate groundwater. Newer farms are experimenting with biogas systems that turn manure into usable energy, offering a partial solution to both waste disposal and rising electricity costs. Whether such technologies become standard practice across the industry, or remain limited to a handful of well-funded operations, will likely shape how sustainably pig farming can continue to expand in the coming decades."], questions: [{ q: "According to the passage, why do farmers gradually change piglets' feed as they grow?", options: ["To stop the piglets from drinking milk before they are ready", "To make the piglets grow larger than their mothers quickly", "To lower the total amount of water the animals need", "To help the pigs put on weight at a steady pace"], answer: 3 }, { q: "What is the main idea of the passage?", options: ["Traditional backyard pig raising has completely replaced large commercial farms", "Government subsidies are the main reason pig farming remains profitable", "Pig farms mainly struggle with controlling disease outbreaks each year", "Modern pig farming blends daily practical care with economic and environmental challenges"], answer: 3 }, { q: "The word \"cull\" in paragraph 3 is closest in meaning to _______.", options: ["trade", "eliminate", "vaccinate", "isolate"], answer: 1 }, { q: "According to the passage, what do many modern pig farms do to prevent disease from spreading?", options: ["They allow outside visitors only during scheduled inspection times", "They sell newly arrived animals within days of purchase", "They restrict visitors and disinfect vehicles entering the farm", "They vaccinate every animal twice a year without exception"], answer: 2 }, { q: "The word \"them\" in paragraph 2 refers to _______.", options: ["the farmers", "older pigs", "piglets", "the pens"], answer: 2 }, { q: "According to the passage, which of the following is NOT mentioned as a factor affecting pork prices?", options: ["Sudden shifts in overall consumer demand", "The total number of pigs a country exports", "Changes in the overall cost of grain", "Subsidies that all governments provide to farmers"], answer: 1 }, { q: "What can be inferred from the passage about farmers who expand their operations during periods of high pork prices?", options: ["Expanding during high prices protects farmers from any future price drop", "Government subsidies help small farms stay in the market longer", "Expanding quickly can leave farmers exposed to falling prices later", "Falling prices are what cause farmers to expand their operations quickly"], answer: 2 }, { q: "According to the passage, how does pig raising relate to Vietnamese culture?", options: ["They are rarely mentioned in traditional Vietnamese celebrations", "They are only raised on large industrial farms nationwide", "They frequently appear in folk stories and traditional festivals", "They were first introduced to Vietnam by foreign traders"], answer: 2 }, { q: "The word \"vocal\" in paragraph 5 is closest in meaning to _______.", options: ["silent", "outspoken", "musical", "official"], answer: 1 }, { q: "What is the author's overall attitude toward the future of pig farming?", options: ["Cautiously hopeful, though uncertain how widely new solutions will spread", "Purely factual about pig prices with no concern for the environment", "Focused only on criticizing large commercial pig farms directly", "Fully confident that new technology will solve every pollution problem"], answer: 0 }] },
    { title: "Advertising the Magic Worldwide: Disney's Global Park Campaigns", paragraphs: ["When the Walt Disney Company promotes its theme parks abroad, it faces a challenge that few advertisers encounter on the same scale: convincing audiences on nearly every continent that a single brand identity can feel both universally magical and personally relevant. Campaigns for parks in Shanghai, Paris, Tokyo, and Orlando share a recognizable visual language, yet subtle differences in tone, humor, and imagery reveal how deeply each market has been studied before a single advertisement airs. This balancing act, more than any individual slogan, may explain why Disney's advertising has become a frequent case study in international marketing courses.", "Rather than simply translating English-language advertisements into other languages, Disney's marketing teams typically rebuild campaigns around local storytelling traditions, holidays, and family customs. In China, for instance, promotional material for Shanghai Disneyland has leaned heavily on themes of multigenerational family togetherness, a value that resonates strongly during major national holidays. European campaigns, by contrast, tend to emphasize fantasy and imagination somewhat more than family duty, though the difference is one of degree rather than a strict rule. Such choices are rarely accidental; they emerge from extensive market research that attempts to predict, however imperfectly, what will move a particular audience to book a trip.", "Over the past decade, television commercials have gradually given up ground to digital platforms, where short videos, interactive filters, and influencer partnerships now carry much of the promotional weight. A single well-placed video featuring a popular local celebrity visiting a park can generate more engagement, at a fraction of the cost, than a traditional prime-time advertisement ever could. This shift has not eliminated large-scale advertising, however; major openings and anniversaries still receive substantial television and outdoor campaigns, suggesting that digital and traditional media now function less as rivals than as complementary tools aimed at different stages of a potential visitor's decision-making process.", "Tourism officials in host cities often argue that a new Disney park delivers economic benefits far beyond ticket sales, and the surrounding evidence, while not conclusive on every point, tends to support at least part of that claim. Hotels, restaurants, and transportation services near Shanghai Disneyland, for example, reported measurable increases in business shortly after the park opened, even among visitors who never entered the gates themselves. Critics counter that such regional advertising campaigns sometimes overstate long-term benefits, since initial surges in visitor spending do not always translate into permanent local employment once the novelty of an opening fades.", "Determining exactly how much any single advertisement contributes to eventual ticket sales remains notoriously difficult, since a visitor's decision to book a trip may be shaped by years of accumulated brand impressions rather than one recent campaign. Marketing researchers therefore rely on indirect measures, such as website traffic spikes following an ad's release or shifts in search-engine interest for a particular park, to estimate impact rather than to prove it outright. These indirect measures suggest a correlation between campaign timing and booking activity, though they cannot fully rule out other explanations, such as seasonal travel patterns that would have driven bookings regardless of any advertising at all.", "Not every campaign succeeds, and Disney's advertising history includes several notable missteps, particularly when messaging designed for one cultural context was applied too directly in another without sufficient adjustment. Such failures have pushed the company toward deeper collaboration with regional marketing agencies rather than relying solely on directives issued from a central office. Looking ahead, industry observers expect that artificial intelligence tools, which can rapidly generate and test dozens of localized ad variations, will further blur the line between global brand consistency and hyper-local advertising, even as questions remain about how such tools might affect the distinctive human storytelling that has long defined Disney's marketing."], questions: [{ q: "What is the main idea of the passage?", options: ["Disney blends consistent branding with local adaptation despite measurement challenges", "Disney's park advertising focuses only on entertainment value, not economic impact", "Local advertising agencies alone determine Disney's global marketing strategy", "Disney relies mainly on television advertising to promote all its parks"], answer: 0 }, { q: "According to the passage, how do European advertising campaigns for Disney parks generally differ from those in China?", options: ["Chinese campaigns focus more heavily on fantasy than family closeness", "European campaigns completely ignore family themes in every advertisement", "European campaigns lean slightly more toward fantasy than family duty", "European campaigns are translated directly from Chinese-language advertisements"], answer: 2 }, { q: "The word \"resonates\" in paragraph 2 is closest in meaning to _______.", options: ["repeats", "overwhelms", "advertises", "appeals"], answer: 3 }, { q: "According to the passage, what has happened to television advertising for Disney parks in recent years?", options: ["It only appears during Disney's slower business seasons", "It has been fully replaced by celebrity influencer videos", "It has completely lost ground to digital advertising everywhere", "It still plays a role for major openings and anniversaries"], answer: 3 }, { q: "The word \"they\" in paragraph 5 refers to _______.", options: ["campaign timing", "these indirect measures", "booking activity", "website traffic spikes"], answer: 1 }, { q: "According to the passage, which of the following is NOT mentioned as a way Disney adapts its advertising internationally?", options: ["Partnering with popular local celebrities in online videos", "Rebuilding campaigns around local holidays and family customs", "Translating English-language advertisements directly into other languages", "Relying entirely on influencer marketing instead of large-scale ads"], answer: 2 }, { q: "What can be inferred about the relationship between digital and traditional advertising for Disney parks?", options: ["The two forms of media likely serve different purposes at different points", "Hotels near Shanghai Disneyland saw a rise in business after opening", "Digital advertising exists because traditional advertising campaigns failed to work", "Traditional media has become completely unnecessary now that digital tools exist"], answer: 0 }, { q: "According to the passage, what do critics say about the economic benefits of Disney park openings?", options: ["They say measurable increases in nearby business happen shortly after opening", "They believe tourism officials always exaggerate every claim they make publicly", "They claim ticket sales alone completely fund all nearby transportation upgrades", "They argue that initial spending increases may not lead to permanent local jobs"], answer: 3 }, { q: "The word \"notoriously\" in paragraph 5 is closest in meaning to _______.", options: ["occasionally", "officially", "famously", "secretly"], answer: 2 }, { q: "What is the author's overall stance toward Disney's global advertising strategy?", options: ["Focused solely on praising Disney's television commercials specifically", "Measured and analytical, acknowledging both strengths and open questions", "Entirely dismissive of Disney's ability to adapt to local markets", "Strictly promotional, written as though for a Disney marketing brochure"], answer: 1 }] },
    { title: "\"Fish Milk\": An Unusual Parallel in Nature", paragraphs: ["Although the word 'milk' evokes images of mammals such as cows or goats, several species of fish have evolved a strikingly similar strategy for feeding their young. Discus fish, a freshwater species popular among aquarium keepers, secrete a thick, nutrient-dense mucus from specialized glands on their skin, which their offspring graze on directly during the first weeks of life. Because this substance performs many of the same biological functions as mammalian milk — delivering concentrated nutrition, antibodies, and hormones to rapidly growing young — some biologists have begun referring to it informally as 'fish milk,' though the term remains a loose analogy rather than a precise scientific classification.", "Laboratory analysis of discus mucus has revealed a composition that shifts noticeably as the fry mature, a pattern that mirrors, at least in broad outline, how mammalian milk changes to match an infant's developmental stage. Early secretions tend to be richer in certain proteins and immune-related compounds, whereas later secretions gradually shift toward a composition better suited to fry that have already begun supplementing their diet with other food sources. Researchers caution, however, that drawing too close a parallel with mammalian lactation risks obscuring important differences, since the underlying glandular structures and hormonal triggers evolved entirely independently.", "Discus fish are not alone in this behavior; certain skates and at least one species of shark have been documented producing comparable secretions, though the evidence for these species remains considerably thinner than for discus fish, resting largely on isolated field observations rather than controlled laboratory study. Some researchers suspect that similar mechanisms may be more widespread among fish than currently documented, largely because such behavior is difficult to observe in wild populations and is easy to overlook in commercial farms that do not routinely monitor for it .", "This biological curiosity has attracted attention well beyond academic ichthyology, largely because it intersects with two pressing practical concerns: the difficulty of rearing certain fish species in captivity, and the search for alternative protein sources that place less strain on land and water resources than conventional dairy farming. Aquaculture operations that raise discus fish commercially have long struggled to replicate natural rearing conditions, since separating fry from parents too early, before the natural mucus-feeding period ends, tends to reduce survival rates and stunt growth even when artificial feed is nutritionally complete on paper.", "A handful of food-science laboratories have begun exploring whether the nutritional profile of fish-derived secretions could inform the design of novel protein supplements, though this line of research remains at an early, largely exploratory stage rather than anything approaching commercial application. Proponents argue that if a stable, scalable extraction method could be developed, such products might offer an unusually nutrient-dense supplement with a considerably smaller environmental footprint than dairy, since fish generally convert feed into biomass more efficiently than cattle do.", "Such optimism, however, invites considerable skepticism from within the scientific community itself. The quantities of mucus a single discus fish produces are minuscule compared to the volumes required for even modest commercial food production, and no researcher has yet proposed a method for scaling extraction without harming the animals or fundamentally altering their natural rearing behavior. Whether 'fish milk' ultimately becomes a meaningful contributor to alternative protein markets, or remains a biological footnote of interest mainly to aquarium hobbyists and evolutionary biologists, will depend on breakthroughs that, at present, exist only as speculative possibilities rather than active research programs."], questions: [{ q: "What is the main idea of the passage?", options: ["Aquaculture researchers have abandoned efforts to farm discus fish commercially", "All fish species produce nutrient-rich secretions for their offspring", "Fish milk research raises intriguing biological questions but remains far from practical application", "Discus fish mucus has already replaced dairy in several commercial products"], answer: 2 }, { q: "According to the passage, how does the composition of discus fish mucus relate to the age of the fry?", options: ["It shifts from early immune-related compounds toward composition suited to older fry", "It changes based on water temperature rather than the fry's age", "It remains chemically identical throughout the entire period fry are fed", "It becomes richer in immune compounds only after fry stop feeding"], answer: 0 }, { q: "The word \"obscuring\" in paragraph 2 is closest in meaning to _______.", options: ["confirming", "measuring", "revealing", "concealing"], answer: 3 }, { q: "According to the passage, what is true about evidence for milk-like secretions in skates and sharks?", options: ["It proves that most wild fish species regularly produce nutrient-rich secretions", "It shows these species produce mucus identical to discus fish exactly", "It rests mostly on scattered field observations instead of lab-based research", "It has been confirmed through extensive laboratory testing across many species"], answer: 2 }, { q: "The word \"it\" in paragraph 3 refers to _______.", options: ["commercial farms", "such behavior", "similar mechanisms", "wild populations"], answer: 1 }, { q: "According to the passage, which of the following is NOT mentioned as a reason 'fish milk' has drawn attention beyond biology?", options: ["Difficulties in rearing certain fish species in captivity", "Fish always converting feed into biomass far more efficiently than cattle", "A search for protein sources less taxing on land and water", "Consumer demand for new aquarium fish breeding techniques"], answer: 3 }, { q: "What can be inferred from the passage about the future of 'fish milk' as a commercial protein source?", options: ["Its commercial success depends on breakthroughs that do not yet exist", "It will almost certainly become a mainstream dairy substitute within years", "Discus fish convert feed into biomass more efficiently than cattle do", "Scaling problems arose because food scientists lost interest in the research"], answer: 0 }, { q: "According to the passage, why do commercial discus operations struggle when fry are separated from parents too early?", options: ["Artificial feed used in such cases is always nutritionally incomplete", "Early separation increases the mucus production rate of adult fish", "Parent fish become aggressive once fry are removed from the tank", "Removing fry before mucus-feeding ends tends to reduce survival and stunt growth"], answer: 3 }, { q: "The word \"minuscule\" in paragraph 6 is closest in meaning to _______.", options: ["tiny", "measured", "variable", "abundant"], answer: 0 }, { q: "What is the author's overall attitude toward 'fish milk' becoming a mainstream food product?", options: ["Genuinely curious but skeptical, given the scale of unresolved obstacles", "Dismissive of the biological phenomenon as scientifically insignificant", "Focused entirely on promoting dairy alternatives over fish research", "Wholly convinced that a commercial breakthrough is close at hand"], answer: 0 }] },
    { title: "Cryptocurrency and Its Shadow Economy of Harm", paragraphs: ["Not only has cryptocurrency attracted enormous capital over the past decade, but it has also drawn a cluster of associated harms that critics increasingly describe, with varying degrees of confidence, as a distinct category of technology-enabled vice. Whether these harms stem primarily from the underlying technology itself or from the speculative culture that has grown up around it remains a matter of genuine scholarly disagreement, one that this discussion does not claim to resolve so much as to map.", "Trading platforms designed to be used from a smartphone at any hour arguably share more design features with gambling applications than early cryptocurrency advocates might care to admit, a resemblance that some researchers argue is deliberate rather than incidental. Features such as constant price notifications, streak-based rewards for frequent trading, and leaderboards ranking the most active users may not, by themselves, prove that platforms are engineered to encourage compulsive behavior, yet their cumulative effect on user psychology tends to mirror patterns long documented in behavioral-addiction research, even if the underlying mechanism differs from that of a slot machine.", "Fraud tied to cryptocurrency has grown increasingly sophisticated, and one particular pattern — sometimes called 'pig butchering,' after the practice of fattening an animal before slaughter — illustrates how thoroughly criminal networks have adapted older confidence-scam techniques to a digital, borderless asset class. Victims are typically cultivated over weeks or months through what appears to be a genuine romantic or friendly relationship, only to be persuaded, once trust is established, to move increasingly large sums into a fraudulent trading platform that displays fabricated gains to encourage further investment. That such schemes can operate across several countries simultaneously, often coordinated by networks that themselves employ trafficked labor, suggests that the harm extends well beyond individual financial loss.", "Energy consumption represents another contested dimension of the debate, though the picture here resists easy generalization. Blockchains that rely on 'proof-of-work' validation, historically the dominant model, consume electricity on a scale comparable to that of some mid-sized countries, a fact regularly cited by critics; newer 'proof-of-stake' systems, however, reduce energy use by a factor that some technical estimates place above ninety-nine percent, which complicates any claim that cryptocurrency is inherently energy-intensive as a category rather than as a consequence of specific design choices some networks happen to retain.", "Concerns about money laundering follow a similarly uneven pattern. Blockchain analysis firms have found that illicit transactions, while real and non-trivial in absolute terms, constitute a comparatively small share of total cryptocurrency activity when measured as a percentage — a finding that complicates, without entirely undermining, the popular perception that digital assets are uniquely favored by criminal enterprises rather than merely one channel among several that criminals happen to use.", "Regulatory responses have varied considerably, from outright bans in some jurisdictions to detailed licensing regimes in others, and the evidence on which approach most effectively reduces consumer harm remains preliminary at best. Regulators in several countries have begun requiring exchanges to verify user identities and monitor for suspicious trading patterns, measures that appear, based on early data, to reduce certain categories of fraud without eliminating them , though it is not yet clear whether more sophisticated scam operations are simply adapting faster than the rules can be updated.", "Taken together, these threads suggest that cryptocurrency's associated harms are neither a fabrication invented by skeptics nor an inevitable feature of the technology itself, but rather an emergent property of how a genuinely novel financial instrument has intersected with existing patterns of fraud, addiction, and regulatory lag. Whether future design choices and policy interventions can meaningfully separate the technology's legitimate uses from its exploitative applications remains, for now, an open question rather than a settled prediction."], questions: [{ q: "What is the main idea of the passage?", options: ["Cryptocurrency is inherently and irredeemably harmful regardless of design choices", "All associated harms are fabrications invented by critics of the technology", "Cryptocurrency's harms arise from a complex mix of technology and circumstance, not a single clear cause", "Energy consumption is the only serious concern surrounding cryptocurrency today"], answer: 2 }, { q: "According to the passage, what does the author suggest about trading-app design features such as notifications and leaderboards?", options: ["They may not prove intent, but their cumulative effect resembles known addiction patterns", "They have no measurable effect on how users behave over time", "They were later removed once researchers linked them to gambling", "They definitively prove that platforms are designed to cause addiction"], answer: 0 }, { q: "The word \"cultivated\" in paragraph 3 is closest in meaning to _______.", options: ["contacted", "harvested", "ignored", "groomed"], answer: 3 }, { q: "According to the passage, why does the author resist calling cryptocurrency inherently energy-intensive as a category?", options: ["Because energy consumption estimates for proof-of-work systems are considered unreliable", "Because proof-of-stake systems were banned in most countries for safety reasons", "Because proof-of-stake systems reportedly use far less energy than proof-of-work ones", "Because no cryptocurrency network has ever used significant amounts of energy"], answer: 2 }, { q: "The word \"them\" in paragraph 6 refers to _______.", options: ["exchanges", "certain categories of fraud", "consumer harm", "early data"], answer: 1 }, { q: "According to the passage, which of the following is NOT presented as true about cryptocurrency-related money laundering?", options: ["The popular perception overstates how uniquely crypto is favored by criminals", "Illicit transactions account for the majority of all cryptocurrency activity", "Digital assets are only one of several channels criminals happen to use", "Illicit transactions make up a relatively small share of total crypto activity"], answer: 1 }, { q: "What can be inferred from the passage about the effectiveness of current cryptocurrency regulation?", options: ["Blockchain analysis firms have found illicit transactions are a small share of total activity", "Fraud rates increased specifically because regulators began requiring identity verification", "Regulation appears to reduce some fraud, but its long-term effectiveness is not yet certain", "Regulation has completely eliminated fraud in every country that has adopted it"], answer: 2 }, { q: "According to the passage, what does the international scope of 'pig butchering' scams suggest?", options: ["That trafficked labor is never involved in operating these schemes", "That the harm reaches beyond the financial losses of individual victims", "That victims are cultivated over weeks through a genuine romantic relationship", "That such scams occur exclusively within a single country's borders"], answer: 1 }, { q: "The word \"preliminary\" in paragraph 6 is closest in meaning to _______.", options: ["official", "tentative", "conclusive", "repeated"], answer: 1 }, { q: "What is the author's overall stance on whether cryptocurrency's harms are inherent to the technology itself?", options: ["Dismissive of concerns raised about scams and addictive trading design", "Firmly convinced that the harms are entirely inherent to the technology", "Balanced and cautious, treating the question as genuinely unresolved", "Focused solely on defending regulators against criticism of their policies"], answer: 2 }] },
  ] },
];
